for class, builds in pairs(ADD) do
  local cd = G.CLASSES[class]
  if cd then
    cd.builds = cd.builds or {}
    local have = {}
    for _, b in ipairs(cd.builds) do have[b.id] = true end
    for _, b in ipairs(builds) do
      if not have[b.id] then cd.builds[#cd.builds + 1] = b end
    end
  end
end
